LASTER CEILING/K & K PRICE LIST.pdf p1"},{"id":"mfg-3df482c7b896","code":"DOR-KNK-016","name":"Door Hinges (2pcs)","category":"WORKS","sub_category":"DOOR","uom":"SET","status":"ACTIVE","cost":450,"description":"K&K section: Doors","branding":"K & K GYPSUM MARKETING SDN BHD","sup_code":"KKGYPSUM","sup_name":"K & K GYPSUM MARKETING SDN BHD","supplier_sku":"","valid_from":"2026-09-11","notes":"catalog-first-import 2026-10: supplier price list, WORK/PLASTER CEILING/K & K PRICE LIST.pdf p1"},{"id":"mfg-a5c29fa78acc","code":"DOR-KNK-017","name":"Door Lock","category":"WORKS","sub_category":"DOOR","uom":"SET","status":"ACTIVE","cost":1400,"description":"K&K section: Doors","branding":"K & K GYPSUM MARKETING SDN BHD","sup_code":"KKGYPSUM","sup_name":"K & K GYPSUM MARKETING SDN BHD","supplier_sku":"","valid_from":"2026-09-11","notes":"catalog-first-import 2026-10: supplier price list, WORK/PLASTER CEILING/K & K PRICE LIST.pdf p1"},{"id":"mfg-3a98fcb0684f","code":"DOR-KNK-018","name":"Door Lock (Canter)","category":"WORKS","sub_category":"DOOR","uom":"SET","status":"ACTIVE","cost":4900,"description":"K&K section: Doors","branding":"K & K GYPSUM MARKETING SDN BHD","sup_code":"KKGYPSUM","sup_name":"K & K GYPSUM MARKETING SDN BHD","supplier_sku":"","valid_from":"2026-09-11","notes":"catalog-first-import 2026-10: supplier price list, WORK/PLASTER CEILING/K & K PRICE LIST.pdf p1"},{"id":"mfg-0a6461e13b10","code":"DOR-KNK-019","name":"Stuguchi Door Closer","category":"WORKS","sub_category":"DOOR","uom":"PCS","status":"ACTIVE","cost":5400,"description":"K&K section: Doors","branding":"K & K GYPSUM MARKETING SDN BHD","sup_code":"KKGYPSUM","sup_name":"K & K GYPSUM MARKETING SDN BHD","supplier_sku":"","valid_from":"2026-09-11","notes":"catalog-first-import 2026-10: supplier price list, WORK/PLASTER CEILING/K & K PRICE LIST.pdf p1"},{"id":"mfg-0d0ff8e28bcb","code":"DOR-KNK-020","name":"Rubber Gasket 2750 153m (per roll)","category":"WORKS","sub_category":"DOOR","uom":"ROLL","status":"ACTIVE","cost":5500,"description":"K&K section: Doors","branding":"K & K GYPSUM MARKETING SDN BHD","sup_code":"KKGYPSUM","sup_name":"K & K GYPSUM MARKETING SDN BHD","supplier_sku":"","valid_from":"2026-09-11","notes":"catalog-first-import 2026-10: supplier price list, WORK/PLASTER CEILING/K & K PRICE LIST.pdf p1"}]$cfi$::jsonb) as x(id text, code text, name text, category text, sub_category text, uom text,
  status text, cost integer, description text, branding text, sup_code text, sup_name text, supplier_sku text,
  valid_from date, notes text);

-- The supplier of each row: matched on code first, then on name (as the setup above matched it).
alter table cfi_rows add column supplier_id uuid;
update cfi_rows r set supplier_id = (
  select s.id from scm.suppliers s where s.company_id = (select id from public.companies where code = 'HOUZS')
     and (upper(s.code) = upper(r.sup_code) or upper(trim(s.name)) = upper(r.sup_name))
   order by (upper(s.code) = upper(r.sup_code)) desc limit 1);

-- Every SKU belongs to a model of its own (model_code = SKU code), as the API's create paths do.
insert into scm.product_models (company_id, model_code, name, category, branding)
select (select id from public.companies where code = 'HOUZS'), r.code, r.name, r.category::scm.mfg_product_category, r.branding from cfi_rows r
on conflict (company_id, model_code, category) do nothing;

-- Works and Service need no photo; the other groups are held Inactive by the photo rule (migration 0062) anyway.
insert into scm.mfg_products (id, company_id, code, name, category, sub_category, uom, status, cost_price_sen, description, branding, model_id)
select r.id, (select id from public.companies where code = 'HOUZS'), r.code, r.name, r.category::scm.mfg_product_category, r.sub_category, r.uom, r.status::scm.mfg_product_status,
       r.cost, r.description, r.branding, m.id
  from cfi_rows r
  left join scm.product_models m on m.company_id = (select id from public.companies where code = 'HOUZS') and m.model_code = r.code and m.category::text = r.category
on conflict (company_id, code) do nothing;

-- One link per supplier and SKU; main only where the SKU has no main supplier yet (uq_smb_one_main).
insert into scm.supplier_material_bindings
    (company_id, supplier_id, material_kind, item_code, material_name, supplier_sku, unit_price_sen, price_valid_from, is_main_supplier, notes)
select (select id from public.companies where code = 'HOUZS'), r.supplier_id, 'mfg_product', r.code, r.name, r.supplier_sku, r.cost, r.valid_from,
       not exists (select 1 from scm.supplier_material_bindings b where b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product'
                                                                    and b.item_code = r.code and b.is_main_supplier),
       r.notes
  from cfi_rows r
 where not exists (select 1 from scm.supplier_material_bindings b where b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product'
                                                                   and b.item_code = r.code and b.supplier_id = r.supplier_id);

-- The cost with its document date, once per supplier, SKU and date.
insert into scm.supplier_binding_price_history
    (company_id, supplier_id, material_kind, item_code, unit_price_sen, is_main_supplier, effective_from, notes, created_by, applied_at)
select (select id from public.companies where code = 'HOUZS'), r.supplier_id, 'mfg_product', r.code, r.cost, b.is_main_supplier, r.valid_from, r.notes, 'catalog-first-import 2026-10', now()
  from cfi_rows r
  join scm.supplier_material_bindings b on b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product'
                                       and b.item_code = r.code and b.supplier_id = r.supplier_id
 where r.valid_from is not null
